window.__D("text/ner-mitzva/c006",{"p":[[2800530004,"<h2>הקדמה</h2>\nכתיב ותאמר ציון<sup data-n=\"1\">1</sup> עזבני ה' וה' שכחני<sup data-n=\"2\">2</sup> וזה פלא גדול לכאורה דאיך יתכן לומר בחי' שכחה למעלה באלקים חיים שהוא ית' למעלה מן הזמן כהוראת שם הויה היה הוה ויהיה כא'<sup data-n=\"3\">3</sup> ואין השכחה שייך רק כאשר בא הדבר בגדר זמן וע\"כ אנו אומרים אין שכחה לפני כסא כבודך<sup data-n=\"4\">4</sup> וזוכר כל הנשכחות<sup data-n=\"5\">5</sup> כו' אך הענין הוא דשכחה זו אינה בעצם אלא היינו רק כמו השכחה שבכנ\"י שגם זה לכאורה כפלא יחשב האיך יפול ענין השכחה בכנ\"י מצד בחי' אור האלקי השוכן בתוכם שנק' שכינה כידוע ששוכן אתם גם בהיות' בגלות בתוך טומאתם<sup data-n=\"6\">6</sup> כו' והוא ענין רוח אלקי שנוססה בכאו\"א מישראל לשוב אל ה' בכל לבבו ולידבק בתו\"מ הגם שיגבר עליהם מאוד עול ד\"א וטרדת העמוקות המבלבלים המוח והלב לגמרי מ\"מ לא ינתק ויפול הנופל לגמרי ח\"ו וכמ\"ש מים רבים לא יוכלו לכבות את האהבה שגם מים רבים דטרדת הפרנסה<sup data-n=\"7\">7</sup> לא יכבה אור אהבה רבה העצמי' שכמו טבע מושרשת בנפשותינו כמ\"ש במ\"א והוא להיותו בחי' אור אלקי (הנק' רוחא דשביק בגווה<sup data-n=\"8\">8</sup> כו') ממש שנק' שכינה שאין בו שינוי וחילוף וז\"ש אני ה' לא שניתי<sup data-n=\"9\">9</sup> ואתם ב\"י לא כליתם דכמו שאני ה' לא שניתי כך גם אור האלקי השוכן בתוך בנ\"י לא כליתם כו' ולכך גם בהיותם בגלות לא מאסתים כו' לכלותם להפר בריתי אתם<sup data-n=\"10\">10</sup> כו' וא\"כ איך יפלו כנ\"י בבחי' שכחה וכמו שנראה בעליל שגם עובדי ה' יוכלו לשכוח לגמרי על ה' בהיותם טרודים ביותר בעסקיהם עד שידמה בעיניו שהכל כחו ועוצם ידו כו' וכמ\"ש השמר לך פן תשכח<sup data-n=\"11\">11</sup> את ה' כו' ובפרט במצליחים במעשיהם כידוע אלא הענין הוא כידוע דיש ב' מדריגות בזה הא' שנופל בו השכחה מפני שעיקר ענין השכחה הוא ע\"י היסח הדעת כשמסיח דעתו ולבו מענין האלקות לגמרי דבאמת אינו מובן לכאורה בב\"פ דק\"ש שבפ\"א אמר ואהבת בכל לבבך ובכל נפשך<sup data-n=\"12\">12</sup> ובפ\"ב אמר ואספת דגנך וכן בפ\"ב אמר לאהבה<sup data-n=\"13\">13</sup> ולעבדו בכל כו' ואם מצד טרדת הפרנסה כמ\"ש ואספת דגנך כו' היה נופל בשכחה שהוא היסח הדעת לגמרי איך יקיים בכל נפשך ממש דלכאורה המה תרתי דסתרי כו' אלא צריך לומר דבחי' השכחה אינו שייך רק במה שבא לכלל דעת והכרה והוא ע\"י ההשגה וההבנה היטב בכלי מוחו ולבו כמ\"ש וידעת היום<sup data-n=\"14\">14</sup> והשבות אל לבבך כי ה' כו' וכן אתה הראת לדעת<sup data-n=\"15\">15</sup> כו' והדעת הוא בחי' טוב ענין ההכר' וההרגש' בכלי המוח והלב כמו ידע שור כו' שנמשך אחריו וישראל לא ידע<sup data-n=\"16\">16</sup> כו' והנה יש בדעת זה שינוי וחילוף והוא ענין הנק' היסח הדעת שהסח' זו היינו ענין הזזה ממקומו כמו שע\"י טרדת אדם בענין גדול מאד יסיח דעתו ולבו לגמרי מענין הקדום כמו מלימודו וכן בלימוד עצמו אמר כי קאי ר' בהאי מסכתא<sup data-n=\"17\">17</sup> כו' וע\"כ נצטווינו השמר לך פן תשכח כו' דמשמע שיוכל להיות שכחה והוא היסח הדעת והיינו מה שנצטווינו בבחי' הדעת שהוא היפך השכחה דהיינו שתמיד נדעה נרדפה<sup data-n=\"18\">18</sup> כו' ולא להסיח מלבנו בחי' דעת זה האלקי אפי' רגע וכמ\"ש דוד לשלמה דע את אלקי<sup data-n=\"19\">19</sup> כו' ומ\"ע דדעת עם הלאו דשכחה הכל אחד דהא בהא תליא דבקיומו",[["1","1","<b>כתיב ותאמר ציון</b>: מיוסד על ד\"ה כה. . זכרתי לך חסד שנדפס במאמרי אדה\"ז על נביאים ע' רב ואילך. וראה מאמרי אדה\"א נ\"ך ע' צז ואילך. וש\"נ. ומלקמן (ו, ב) ראה סה\"מ תקס\"ה ח\"ב ע' תשמג ואילך. ע' תשלז ואילך. לקו\"ת ואתחנן ה, סע\"ד ואילך. אוה\"ת ואתחנן ע' קעו ואילך."],["2","2","<b>ותאמר ציון. . שכחני</b>: ישעי' מט, יד."],["3","3","<b>שם הויה. . כא'</b>: ראה שהיחוה\"א פ\"ז. הנסמן בתו\"ח מקץ ריט, ד הערה 62."],["4","4","<b>אין שכחה. . כבודך</b>: ברכת זכרונות (תפלת מוסף לר\"ה). ראה הנסמן במאמרי אדה\"א נ\"ך ע' פז."],["5","5","<b>וזוכר כל הנשכחות</b>: ברכת זכרונות [ושם: כי זוכר]."],["6","6","<b>ששוכן אתם. . בתוך טומאתם</b>: אחרי טז, טז."],["7","7","<b>מים רבים. . דטרדת הפרנסה</b>: שה\"ש ח, ז. ראה תו\"א ר\"פ נח. תו\"ח שם נח, ד ובהערה 6. שע\"ת ח\"א טו, א."],["8","8","<b>רוחא דשביק בגווה</b>: ראה זהר משפטים צט, ב. ע\"ח (שער מ\"ן ומ\"ד) של\"ט, דרוש ז. ח. הנסמן במאמרי אדה\"א דברים ח\"א ע' כד."],["9","9","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו. ראה גם תו\"ח נח נט, א ובהערה 12."],["10","10","<b>לא מאסתים. . אתם</b>: בחוקותי כו, מד."],["11","11","<b>השמר לך פן תשכח</b>: ואתחנן ו, יב. עקב ח, יא."],["12","12","<b>ואהבת. . ובכל נפשך</b>: ואתחנן ו, ה [בדילוג]."],["13","13","<b>ואספת דגנך. . לאהבה</b>: עקב יא, יד. יג [בדילוג]."],["14","14","<b>וידעת היום</b>: ואתחנן ד, לט."],["15","15","<b>אתה הראת לדעת</b>: ואתחנן שם, לה."],["16","16","<b>ידע שור. . וישראל לא ידע</b>: ישעי' א, ג."],["17","17","<b>כי קאי ר' בהאי מסכתא</b>: ראה שבת ג, ריש ע\"ב."],["18","18","<b>נדעה נרדפה</b>: הושע ו, ג."],["19","19","<b>דע את אלקי</b>: דהי\"א כח, ט."]]],[2800530005,"מצות הדעת בתמידות לא יבא לכלל שכחה שהוא היסח הדעת ובעברו על לאו דלא תשכח<sup data-n=\"20\">20</sup> כו' ממילא אין זה רק מפני שלא קיים מ\"ע דדעת כי אין השכחה באה רק מהיסח הדעת ואמנם בסיב' השכח' יבא לכלל פר\"ע לגמרי לעבור על עבירות חמורות כמ\"ש ישראל לא ידע עמי לא התבונן הוי גוי חוטא<sup data-n=\"21\">21</sup> עם כבד עון דלכאורה כפלא יחשב איך בשביל חסרון הדעת והתבוננות לבד יהיה נק' חוטא וכבד עון כו' אלא מפני שהיסח הדעת וההכר' שהוא השכחה מביאה לבחי' פר\"ע לגמרי ולכך אמר השמר לך פן תשכח כו' ולכך הוכיח הנביא לבנ\"י ידע שור קונהו כו' ישראל לא ידע ע\"כ הוי גוי חוטא כו' שכל הסתעפות הרע גמור אינו בא רק מסיבת השכחה לגמרי שהוא רק עוצם היסח הדעת לבד וד\"ל. אך מדריג' הב' בכנ\"י הוא למעל' מעל' מבחי' הדעת וההשג' האלקי' הנתפסת בכלי המוח והלב בכל חד וחד לפום שיעורא דילי'<sup data-n=\"22\">22</sup> והוא מ\"ש ואהבת בכל נפשך במס\"נ ממש שלמעלה מן הדעת וההכר' ששוה היא בכל נפש גדול וקטן והוא בחי' אור האלקי המושרש בעצם הנפש בתוך תוכה ופנימיות' העצמי שנק' תעלומת הלב<sup data-n=\"23\">23</sup> או נקודת הלב כידוע שמכח זה העצמי יכולים הכל למס\"נ על קדה\"ש כו' ובזה לא יפול ענין השכח' כלל וכלל כי אין בו שינוי וחילוף כלל כי אור אלקי זה מאיר תמיד בקביעות בנקוד' הלב בלי הפסק ושינוי כלל והיינו בחי' יחידה שבנפש כידוע שע\"ז אמר כנ\"י שימני כחותם<sup data-n=\"24\">24</sup> על לבך כמו החותם שהאותיות חקוקים בו כך כל עצם אור הנשמה דבוקה וחקוק' בלבך כמ\"ש בזהר דאע\"ג דאזיל הכא והכא דיוקני אשתאר בך<sup data-n=\"25\">25</sup> כו' פי' אזיל הכא כו' הן בחי' מוחא ולבא שמוטרדים בתכלית עד שיפול שם בחי' שכח' והיסח הדעת לגמרי כנ\"ל מ\"מ דיוקני שהוא בחי' נקודת פנימי' הלב והוא עצם נקודת הרצון שלמעל' גם מהתפעלות הרצון כי התפעלות הרצון יפול בו שינוי וחילוף כמו בטרדת פרנס' אבל עצם נקודת הלב לתכלית עומקו לא יפול בשינוי כלל ותמיד דבוק למעל' והוא הנק' שכינ' בכללות נ\"י כידוע שז\"ש חבוק' ודבוק' בך<sup data-n=\"26\">26</sup> דהיינו דיוקני אשתאר בך כחותם כו' וניכר' נקודה עצמי' זו במס\"נ על קדה\"ש ובבע\"ת אמיתית כראב\"ד שיצא' נשמתו בבכי'<sup data-n=\"27\">27</sup> וכה\"ג כידוע. ובזה יובן ענין ואספת דגנך שאינו סותר כלל לאור אה\"ר דבכל נפשך זה וד\"ל:\n<b>וזהו</b> ותאמר ציון בחי' פנימי' נקודת הלב שנק' ציון המצוינת<sup data-n=\"28\">28</sup> כו' עזבני ה' וה' שכחני דזהו כמתמיה איך ה' שכחני דודאי כמים הפנים אל פנים<sup data-n=\"29\">29</sup> כו' ואם יש שכחה בכנ\"י מצד בחי' הדעת האלקי שיפול בשכחה לפרקים כנ\"ל ובכללות נק' סוכת דוד הנופלת<sup data-n=\"30\">30</sup> כו' הנה זהו רק מצד בחי' כלי המקבל דמוחא ולבא דכנ\"י שמחמת עוצם טרדת' העמוק' יבלבל המוח והלב לגמרי עד שיבואו לכלל שכחה לגמרי שהוא ענין היסח הדעת כנ\"ל שיש בזה הפסק ושינוי תמיד אבל מצד בחי' פנימי' נקודת הלב שלהם ששם אין שינוי וחילוף כלל להיותו בבחי' אלקות ממש שנק'",[["20","20","<b>לאו דלא תשכח</b>: ראה סה\"מ (להרמב\"ם) מל\"ת א לדעת הרמב\"ן. ס' חרדים בשם ר\"י מל\"ת התלויות בלב ו. ז."],["21","21","<b>הוי גוי חוטא</b>: ישעי' א, ד."],["22","22","<b>בכל חד וחד לפום שיעורא דילי'</b>: ראה הקדמת התניא ע\"פ הזהר וירא קג, ריש ע\"ב."],["23","23","<b>תעלומת הלב</b>: תהלים מד, כב. ראה גם מאמרי אדה\"א שמות ח\"ב ע' שצב. וש\"נ. שע\"ת ח\"א ז, א ובהנסמן במ\"מ לשם."],["24","24","<b>שימני כחותם</b>: שה\"ש ח, ו."],["25","25","<b>דאע\"ג דאזיל. . בך</b>: ראה זהר ויחי רמד, סע\"ב ואילך. (סבא) משפטים קיד, א."],["26","26","<b>חבוק' ודבוק' בך</b>: לשון הושענא אום אני חומה (ליום ג')."],["27","27","<b>כראב\"ד שיצא' נשמתו בבכי'</b>: ע\"ז יז, א. ראה סה\"מ תרמ\"ו ע' יט."],["28","28","<b>ציון המצוינת</b>: לשון הושענא אבן שתי' (ליום ב')."],["29","29","<b>כמים הפנים אל פנים</b>: ע\"פ משלי כז, יט."],["30","30","<b>סוכת דוד הנופלת</b>: עמוס ט, יא. ראה זהר תצוה קפו, ב. מאמרי אדה\"א נ\"ך ס\"ע שנב. וש\"נ."]]],[2800530006,"שכינה כנ\"ל ודאי כמים הפנים א\"פ למעל' ג\"כ מאיר מבחי' אור פנימי' ועצמות אלקו' שנק' סובב כ\"ע שלמעל' מהתלבשות אור האלקי בזמן ומקום כידוע שלא שייך שם בחי' שכחה כלל וכלל וכמו שאנו אומרים אין שכחה לפני כסא כבודך לפני דוקא וא\"כ איך ה' שכחני והלא נאמר אני ה' לא שניתי כו' כך אתם ב\"י לא כליתם וכן לא מאסתים לכלותם להפר בריתי מטעם הנ\"ל וד\"ל. אך הנה יש להבין דלפ\"ז אין הדבר תלוי רק בכמים הפא\"פ כו' ולמה בגלות מצרים שהיו משועבדים בתכלית הדוחק לא נגאלו עד שידע והרגיש בצרתם כמ\"ש ותעל שועתם<sup data-n=\"31\">1</sup> כו' וידע אלקים<sup data-n=\"32\">2</sup> וכן אמר למשה וגם אני שמעתי<sup data-n=\"33\">3</sup> את נאקת בנ\"י כו' ואזכור את בריתי כו' דמשמע שכל ימי משך גלותם הקשה לא נזכר עליהם ואיך יש שכחה לפניו ית' מאחר ששוכן אתם כו' בבחי' פנימי' ועצמיות ממש שלמעלה מבחי' הדעת שאינו שייך לבא לבחי' שכחה כלל מטעם הנ\"ל וגם בנ\"י היו אז בהתקשרות עצמיות שלמעלה מבחי' הדעת אלקי כי לא ידעו את ה' ותורתו עד עמדם בהר סיני בשעת מ\"ת כו' אמנם הנה ידוע שלא נגאלו ישראל ממצרים רק ע\"י כח וזכות האמונה הפשוט' שלהם דוקא שהי' מושרש ונטוע בנפשם מצד הירושה מאבותיהם בלבד וז\"ש כה אמר ה' זכרתי לך<sup data-n=\"34\">4</sup> חסד נעוריך חסד נעוריך דוקא בגלות מצרים הוא שזכרתי לך בזכרון עולם שבחי' הזכרון הוא למעל' מן השכחה שלא ישכח לעולם כו'. והענין הוא כידוע שיש ב' מיני דעת ד\"ע וד\"ת וכמ\"ש כי אל דעות ה'<sup data-n=\"35\">5</sup> כו' וביאור הדברים ידוע שב' מיני שפע הן הא' התהוות מאין האלקי לבחי' יש שאור האלקי מוסתר שזהו ד\"ת כמו שהוא לגבי המקבל וד\"ע הוא בחי' אור שפע העליונה שנמשך ממהו\"ע דקמי' כלא חשיבא ולע\"ל יתגל' בחי' עצמות אלקות כמו שהוא וז\"ש כולם ידעו אותי<sup data-n=\"36\">6</sup> ממש כי נגל' כבוד הוי'<sup data-n=\"37\">7</sup> עצמו וכן כתיב ומלא' הארץ דעה<sup data-n=\"38\">8</sup> את הוי' ממש אך בגלות מצרים היה זה רק בבחי' אמונה פשוטה וחזקה בירושה מאבותיהם ולכך זכו שנגלה עליהם כו' מבחי' מהו\"ע ממש (וכמשי\"ת בדרוש דמצה וקי\"ס<sup data-n=\"39\">10</sup> באורך) וזהו וידע אלקים בידיעה דד\"ע כמו שהוא בכבודו ובעצמו כמו לע\"ל והוא שהרגיש וידע בצרתם כמו שיודע ומרגיש לבחי' מוה\"ע<sup data-n=\"40\">9</sup> ממש כמו בכל צרתם לו צר<sup data-n=\"41\">11</sup> ממש ואמנם בחי' ד\"ת הוא בחי' הידיע' וההשגח' האלקי' שיודע ומבין כל מעשה בנ\"א שהוא כסדר ההשתלשלות מאין ליש שהוא בבחי' צמצום והסתר עד שיוכל להיות בבחי' חיצוני' ואחוריים שזה כמו בכל גלות שהוא בהסתר פנים כמ\"ש ואנכי הסתר אסתיר פני<sup data-n=\"42\">12</sup> ואמר בזהר דקוב\"ה בגלותא אסתלק לעילא לעילא<sup data-n=\"43\">13</sup> כו' וכמ\"ש אלך אשובה אל מקומי<sup data-n=\"44\">14</sup> כו' כי הוא תפיס בכ\"ע<sup data-n=\"45\">15</sup> ולית מאן דת\"ב וכמאמר הוא מקש\"ע<sup data-n=\"46\">16</sup> ואין העולם מקומו כידוע אך ע\"י האמונ' הפשוטה דוקא להיות' בבחי' פנימי' ועצמיות ממש שלא יפול בה בחי' שכחה כלל כנ\"ל מעוררים למעלה ג\"כ מבחי' מוה\"ע שאין שם שינוי גם ברו' הקטרוגים כו' וכמ\"ש לא מאסתים כו' וכן אתם בנ\"י לא כליתם כנ\"ל",[["31","1","<b>ותעל שועתם</b>: שמות ב, כג."],["32","2","<b>וידע אלקים</b>: שם שם, כה."],["33","3","<b>וגם אני שמעתי</b>: וארא ו, ה."],["34","4","<b>כה. . זכרתי לך</b>: ירמי' ב, ב."],["35","5","<b>כי אל דעות ה'</b>: שמו\"א ב, ג. ראה מאמרי אדה\"א ויקרא ח\"א ע' רסב. וש\"נ. תו\"ח בראשית יח, ג ובהערה 11. לקמן נא, ב."],["36","6","<b>כולם ידעו אותי</b>: ירמי' לא, לג."],["37","7","<b>נגל' כבוד הוי'</b>: ישעי' מ, ה."],["38","8","<b>ומלא' הארץ דעה</b>: ישעי' יא, ט [ושם: כי מלאה ? ראה לקמן יב, ב. לא, ב. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' רסט. שע\"ת קמא, ג ובמ\"מ לשם]."],["39","10","<b>בדרוש דמצה וקי\"ס</b>: בפנים הספר (שער האמונה)."],["40","9","<b>מוה\"ע</b>: מהות ועצמות ? כ\"ה כמ\"פ בדרושי כ\"ק אדה\"א (הוא\"ו לפני הה\"א). ובכ\"מ תקנו המדפיסים מהו\"ע. ואכ\"מ."],["41","11","<b>בכל צרתם לו צר</b>: נסמן בסמוך בהערה 17."],["42","12","<b>ואנכי הסתר אסתיר פני</b>: וילך לא, יח."],["43","13","<b>דקוב\"ה. . לעילא לעילא</b>: ראה זהר ויגש רי, א. ויקרא כ, ב. הנסמן בתו\"ח לך צה, א הערה 2."],["44","14","<b>אלך אשובה אל מקומי</b>: הושע ה, טו. כ\"ה בדפו\"ר. ובהמדורת לעמבערג נדפס ואשובה (בהוספת וא\"ו) והוא הוספת המדפיס."],["45","15","<b>הוא תפיס בכ\"ע</b>: נסמן לקמן קטו, ב."],["46","16","<b>הוא מקש\"ע</b>: ראה ב\"ר פס\"ח, ט. הנסמן בתו\"ח בראשית מג, א הערה 2."]]],[2800530007,"ע\"כ בצרתם לו צר ממש כאב שמרגיש בצרת בנו כמו שמרגיש בצרת עצמו ממש וזהו לו צר ממש משא\"כ בידיעה שחוץ ממנו כפי סדר ההשתלשלות לא צר<sup data-n=\"47\">17</sup> בא' וכן לענין כי הוא עשנו ולא ולו אנחנו<sup data-n=\"48\">18</sup> כו' וכן ולו נתכנו ולא<sup data-n=\"49\">19</sup> כי גם שעיניך פקוחות<sup data-n=\"50\">20</sup> על כל דרכי כו' יוכל להיות בזה בחי' שכחה והיסח הדעת שזהו מ\"ש כנ\"י עזבני ה' וה' שכחני מפני שגם הם שכחו ועזבו את ה' כמ\"ש אותי עזבו<sup data-n=\"51\">21</sup> כו' אבל בבחי' פנימית נקודת הלב ששם נטוע האמונה החזקה כמו טבעי' ועצמי' ממש ע\"ז אומר אין שכחה לפני כסא כבודיך כו' וזהו שהשיב לציון התשכח אשה<sup data-n=\"52\">22</sup> כו' כי בנים אתם<sup data-n=\"53\">23</sup> כו' וד\"ל והנה מה שהיה בכנ\"י בגלות מצרים בבחי' האמונ' הפשוטה יזכו לע\"ל להיות בבחי' ראי' במהו\"ע ממש וקצתו זכו במ\"ת שכל העם רואים<sup data-n=\"54\">24</sup> כו' (כמשי\"ת בפנים באריכות) וזהו זכרתי לך לע\"ל לבחי' חסד נעוריך דוקא שיצאו באמונה פשוטה לבד שלמעלה מן הדעת וההכרה במוח ולב כנ\"ל וע\"כ גם בנ\"י נצטוו לזכור יצ\"מ כל הימים כמ\"ש למען תזכור<sup data-n=\"55\">25</sup> יום צאתך מא\"מ כל ימי חייך אפי' לימות המשיח והעה\"ב כמבואר בדברי רז\"ל משום דהא בהא תליא דכמו שמלמעלה למטה זכרתי לך בבחינת הזכרון שאין בו שינוי כך מלמטה למעלה בכנ\"י תזכור גם לעוה\"ב שאז יבאו לבחי' הראי' ממש כמ\"ש הנה אלקינו זה<sup data-n=\"56\">26</sup> לנוכח כו' ובלא שינוי עוד כלל וכלל וד\"ל:\n<b>ומעתה</b> יש להבין במ\"ש עוד בזה הזכרון דזכרתי לך חסד נעורייך דוקא שלבד כח האמונה שהאמינו למשה בהיותם במצרים הלכו אחרי ה' במדבר בארץ לא זרועה והוא מ\"ש לכתך אחרי במדבר<sup data-n=\"57\">27</sup> כו' ויובן זה עד\"מ הידוע באב שיש לו בן קטן יקר וחביב לו ביותר ורוצה לנסותו בב' דברים בחכמתו ודעתו ובטוב לבבו הנאמן אם הוא מקושר באהבה אמיתית לאביו במס\"נ ממש ובמה מנסהו אם האב תמיד עמו בקירוב ובכל דברי חפץ נותן לו אין זה חידוש בהמצא לב הבן נאמן בכל לאביו אך הנה האב מסתתר ומתרחק מבנו במקום מוצנע ונעלם ביותר כדי שיצר לבנו ויחפשנו היטב ואז יראה האב תכלית נקודת לבבו אליו והנה מיד שנעלם האב מן הבן יצר לבן זה מאד וירוץ בכל כחו לחפש אותו ובזה נראה תוך לב הבן בחפשו היטב אחר האב והנה אחר שיחפש הבן בכל דרכים ומסילות שיודע הבן שהן דרכים ומסילות שהולך בהן אביו בכל יום ולא ימצאנו ודאי יצר לו ויבכה תמיד על אשר ניטל ממנו אביו מאור עיניו וחיי ראשו ותמיד במסתרים תבכה נפשו בלתי תתנחם עד שאומר נואש בנפשו שלא יראה עוד פני אביו לעולם ובהמשך הזמן שכבר נתייאש בדבר זה תתקרר המרירות בלבו וישכח מלבו מעט מעט עד שיתרשל לחפש את אביו לגמרי ופוסק מלבכות עוד שנמצא נפסק חבל התקשרות הבן לאביו לגמרי וכל זה בא מב' דברים הא' מיעוט דעת התינוק שדעתו קצרה ולא יבין ויכיר איך שאביו מנסהו בזה ואין ההסתר שהסתיר עצמו",[["47","17","<b>בצרתם לו צר. . לא צר</b>: ישעי' סג, ט. ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תש ובהנסמן במ\"מ לשם. מאמרי אדה\"א בראשית ע' שעז. תו\"ח וירא ק, א."],["48","18","<b>כי הוא עשנו ולא ולו אנחנו</b>: תהלים ק, ג [בדילוג]. ראה גם מאמרי אדה\"א דברים ח\"ב ע' תתיג."],["49","19","<b>ולו נתכנו ולא</b>: שמו\"א ב, ג. ראה זהר (אד\"ז) האזינו רצב, סע\"ב. ראה גם תו\"ח לך פח, ד ובהערה 25."],["50","20","<b>שעיניך פקוחות</b>: ירמי' לב, יט."],["51","21","<b>אותי עזבו</b>: ירמי' ב, יג."],["52","22","<b>התשכח אשה</b>: ישעי' מד, טו."],["53","23","<b>בנים אתם</b>: פ' ראה יד, א."],["54","24","<b>שכל העם רואים</b>: יתרו כ, טו."],["55","25","<b>למען תזכור</b>: פ' ראה טז, ג. ראה ברכות יב, ב. לקמן ט, ב. לא, א. מט, ב. פג, א. מאמרי אדה\"א שמות ח\"א ס\"ע צב. ח\"ב ע' תנ. במדבר ח\"ב ע' תיט. נ\"ך ס\"ע שצו ואילך וע' תכה."],["56","26","<b>הנה אלקינו זה</b>: ישעי' כה, ט."],["57","27","<b>לכתך אחרי במדבר</b>: המשך הכתוב כה. . זכרתי לך חסד נעוריך."]]],[2800530008,"אמיתית מצד העצ' והרחקה זו שנתרחק אינה אמת שעתידה לבא לקירוב כי לא נתרחק האב באמת מצד שנאה רק שחפץ לנסותו לדעת את אשר בלבבו כו' והב' שביאוש זה שהבן מתיאש בנפשו הנה נראה בזה מיעוט אהבת והתקשרות הבן שאינה נאמנה כ\"כ לאביו שאם היתה התקשרותו חזקה לא היה נופל ביאוש כלל כי לב הבן הנאמן יתחזק בכל כחו לחפש אחר אביו וגם בהיותו מוסתר ונעלם מעיניו לא יפול ביאוש כלל כי יודע בלבו היטב שאמונתו והתקשרותו חזק וכך כמים הפא\"פ כו' ודאי לב אביו אליו ולא הסתיר א\"ע רק לנסותו לבד וזהו בן חכם ונאמן בכל לבו שמשכיל ע\"ד ההסתר שאינו אמיתי וגם יחפשנו תמיד בכל דרכי האב וגם אם לא ימצאנו לא יבכה כלל לומר נואש בנפשו אדרבה תמיד יבקשנו בכל לבו ויחפשנו בכל דרכי נתיבות האב לילך בעקבות אביו במסילות שדרך בהן רגלי האב ובכל מקומות שהיה רגיל להמצ' שמה וגם אם אינו מוצא לאביו בדרכים שלו ישמח בנפשו ומובטח שבדרכי האב הולך שם ודאי ימצאנו ופן ימצאנו לאב הולך מרחוק ילך אחריו וידבקנו גם אם לא יראה פני האב מקרוב הלך ילך מאחוריו מרחוק ויגיל וישמח בזה כאילו רואהו מקרוב פא\"פ ממש מאחר שיודע שדרכים הללו דרכי האב הן ומתאמץ לרוץ בהן גם שיראנו בהן רק מאחוריו כו' והנה כאשר האב רואה עוצם השתדלות הבן לחפש אותו בדרכיו לראותו גם מאחוריו ואינו מתייאש כלל הרי רואה גודל התקשרותו הנאמנה לרוץ אחריו גם בחושך ואפלה וגם שאינו רואה לאביו בדרכים הללו ילך וירוץ בכל כחו עוז גם שלא יראה פניו כו' אזי מתעורר בלב האב אה\"ר בכפלי כפלים מכמו שהיה לו בתחלה לבנו כי לא יוכל האב להתאפק ומתגלה אליו ממקום המוצנע שהסתיר את עצמו ומראה לו הארת פנים מפנימי' הלב ותוך תוכו באה\"ר שלא יכילנו הכלי עד שישקנו מנשיקות פיהו לבנו בנשיקין כפולים כמו האב שמשתעשע בבנו יקירו שנושקו כפלים כי לא יספיק בלבו נשיקה אחת עד שישקנו עוד הפעם מרוב אהבתו אליו בחיבה יתירה וגם כאן הרי האהבה לבנו חביבו כבר היה בלבו וממילא בעת שהסתיר עצמו הרי נתרחק והעלים אור האה\"ר בלבו לבלתי הגלות אליו כלל. ואמנם בחי' התאפקות זו אחרי ראותו עוצם התקשרות הבן נאמנה בנסיון זה שנסהו ונמצא לבבו נאמן לחפשנו בכל לבו גם בהיותו בהסתר מאתו כנ\"ל אז כאשר מחזיר לו פניו יבא האב לכלל התפעלות אה\"ר וחיבה יתירה לבנו עד שמנשקו נשיקין כפולים כי הרי הוכפלה אור האה\"ר בכפלי כפלים מכמו שהיה תחלה קודם שנתרחק מאתו כי הנה אה\"ר זו שיצא' בגלוי עתה אחר הנסיון בריחוקו ממנו באה מפנימי' ועצמות עומק הלב הרבה יותר מכמו שהיה בלבו אליו בעת הקירוב ודוקא מצד ההעלם והריחוק שבזה נאמנה האהבה של הבן ביותר להיותה באה מן הריחוק בתוספות עוז מכמו שהיא בקרוב וכך הוא מן האב אל הבן שמן הריחוק שנתרחק מבנו יתוסף אהבתו אליו"],[2800530009,"בכפלים בהמצאו לבן באור הארת פניו כאשר נמצא לב הבן נאמן בנסיון מטעם הנ\"ל וזהו הנק' נשיקין כפולים דוקא וד\"ל:\n<b>והנמשל</b> מכל פרטי המשל הנ\"ל יובן ג\"כ עד\"ז ממש באהב' ה' לישראל שנק' בנים כמ\"ש לע\"ל והשיב לב אבות<sup data-n=\"58\">1</sup> כו' שאהבת כנ\"י שנק' בנים בהיותם בקירוב גדול ברוב עוז וחיבה פא\"פ עם אביהם שבשמים כמו במ\"ת שדיבר עמהם פב\"פ וכה\"ג גם בזמן בהמ\"ק ראשון בימי שלמה כו' אין זה חידוש כ\"כ ואמנם כאשר חפץ ה' לנסותם מסתיר פניו מהם כמו בזמן הגלות דכתיב אתה אל מסתתר<sup data-n=\"59\">2</sup> כו' כמ\"ש דאסתלק לעילא לעילא<sup data-n=\"60\">3</sup> כו' ובנ\"י בשעבוד קשה בטרדת פרנסה בנפשם ממש יביאו לחמם ובעוצם הלחץ והדחק עד מיצוי הנפש ממש ועכ\"ז גם בקוצר רוח ועבודה קשה שמררו חייהם לא נסוג אחור לבבם ולא נתיאשו מלדרוש ולבקש את ה' בכל לבבם ונפשם בתו\"מ ותפלה ותשובה מעומק' דלבא כמ\"ש והיה בצר לך ומצאוך<sup data-n=\"61\">4</sup> כו' ובקשתם משם את ה' כו' כי תדרשנו בכל לבבך<sup data-n=\"62\">5</sup> כו' כמשל בן הנאמן בהתקשרות עוז אהבתו וחכם ומבין שהרחקה זו שנתרחק מאביו אינו רק לנסותו לדעת אשר בלבבו אם יתחזק כו' כנ\"ל ומתחזק בכל עוז לחפשו בכל דרכים ומסילות שהאב הולך תמיד כו' והיינו ענין ההילוך אחרי ה' בתורתו ועבודתו במצות שנקראו דרכי הויה ואורחות ה'<sup data-n=\"63\">6</sup> שגם שאינו רואה פני אור ה' כי המצות מלובשים בדברים גשמיים כצמר דציצית וקלף דד' פ' דתפילין וכה\"ג ה\"ז כהולך במסילות ודרכים שהאב הולך שם מאחר שנק' אורחות ה' כמ\"ש דוד בפקודיך אשיחה<sup data-n=\"64\">7</sup> ואביטה אורחותיך אורחות שה' בעצמו הולך שם והיינו בחי' פנימית רצון העליון שמוסתר במצות שנקרא דרך ה' ממש וכמ\"ש ושמרו דרך ה'<sup data-n=\"65\">8</sup> עד\"מ ההולך בנתיבות ומסילות שהמלך הולך שם אעפ\"י שאינו רואהו רק מאחוריו ילך אחריו וז\"ש אחרי ה' תלכו<sup data-n=\"66\">9</sup> רק אחרי ה' לילך בהילוך דרכיו בתו\"מ כל היום וכמ\"ש אביטה אורחותיך ממש וע\"י התאמצות יתירה לילך אחרי ה' בדרכי התו\"מ גם בהיותו בבחי' הריחוק וההסתר אם מצד הקוצר רוח כו' ואם מצד הסתר אלקות בזמן הגלות ושניהם אמת וגם שרק מרחוק ה' נראה בהילוך זה בדרכי התו\"מ בבחי' חיצוניות ואחוריים אחרי ה' כנ\"ל מ\"מ יתחזק במעוזו שלא יסוג לבו אחור עכ\"פ במחשבה ודיבור בד\"ת להיות דורש ומבקש ה'. והנה כאשר רואה האב השתדלות הבן גם בריחוק יתוסף אהבתו בכפלי' כנ\"ל כך עי\"ז יתוסף אור אהבת ה' לישראל בכפלי' ונק' נשיקין כפולים כנ\"ל כי ה' מחזיר פניו באור אה\"ר בכפלי' להאיר נפשנו מפנימי' אור פניו יותר מזמן מ\"ת דכתיב ישקני מנשיקות פיהו (שהן טעמי תורה<sup data-n=\"67\">10</sup> כידוע) והיינו בחי' נשיקין כפולים הנ\"ל שבא דוקא בסיבת הריחוק אחר הנסיון שגדול בכפלי' מאהבה שבקירוב בהיותו פב\"פ וד\"ל וכמ\"כ יובן בענין התפלה שבמקום קרבן<sup data-n=\"68\">11</sup> שבבהמ\"ק שבזמן הגלות ודאי בחי' הסתר אלקות גם ברוב יגיעה בעבודה",[["58","1","<b>והשיב לב אבות</b>: מלאכי ג, כד."],["59","2","<b>אתה אל מסתתר</b>: ישעי' מה, טו."],["60","3","<b>דאסתלק לעילא לעילא</b>: נסמן לעיל ב, א הערה דקוב\"ה."],["61","4","<b>והיה בצר לך ומצאוך</b>: ואתחנן ד, ל [בהוספת תיבת ?והיה\"]."],["62","5","<b>ובקשתם משם. . לבבך</b>: ואתחנן שם, כט."],["63","6","<b>דרכי הויה ואורחות ה'</b>: הושע יד, י. תהלים כה, י. ראה ביאוה\"ז וישלח יט, ב. שע\"ת ח\"א לב, א. הנסמן במאמרי אדה\"א קונטרסים ע' שכד."],["64","7","<b>בפקודיך אשיחה</b>: תהלים קיט, טו."],["65","8","<b>ושמרו דרך ה'</b>: וירא יח, יט."],["66","9","<b>אחרי ה' תלכו</b>: פ' ראה יג, ה [ושם: ה\"א]."],["67","10","<b>ישקני. . טעמי תורה</b>: שה\"ש א, ב. וראה רש\"י שם. להלן (כו, א) בשם המדרש. (פח, סע\"ב) וכדפרש\"י. וראה מאמרי אדה\"א דברים ח\"ד ס\"ע א'תעג ואילך."],["68","11","<b>התפלה שבמקום קרבן</b>: ראה ברכות כו, א-ב. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."]]],[2800530010,"שבלב ומוח הרי יגברו המונעי' הן המ\"ז המבלבלים מצד עומק התקשרות המוח והלב המקושר בעניני פרנסתו וכה\"ג בלא\"ה יתגבר כח הסט\"א לבלבל המוח והלב כדי שלא יוכל לבא לבחי' נקודת הלב הפנימית כלל כמו האב שמסתתר גם שהבן מחפשו ביותר אינו מוצאו וכמ\"ש ביום ההוא אסתיר פני<sup data-n=\"69\">1</sup> אסתיר פני פנימי' דהוי' שהוא בחי' סובב כ\"ע שאינו נתפס בגלוי בלב רק רואה ה' מרחוק מאד כו' ועכ\"ז לא נסוג אחור לבו ולא יאמר נואש בנפשו כלל ויתחזק בכל עוז לדרוש ולבקש ה' בעבודה שבלב ומוח בתפלה גם בהיותו בהעלם והסתר ילך בכל כחו אחרי ה' ונמשך אחריו בכל לבו כמו הבן שנמשך והולך לבקש אביו וכתיב ובקשתם משם כו' כי תדרשנו כו' אז ודאי יחזיר ה' לו פניו באור פנימי' אה\"ר בכפלי' שנק' נשיקין כפולים מטעם משל הנ\"ל וד\"ל. וזהו זכרתי לך כו' לכתך אחרי דוקא כי ביצ\"מ היו בנסיונות גדולים שה' ניסה אותם כמו ברדיפת פרעה<sup data-n=\"70\">2</sup> וחילו אחריהם וכה\"ג בלכתם במדבר בלא מים<sup data-n=\"71\">3</sup> והילוכם הי' רק אחרי ה' היינו מרחוק ביותר כי לא ראו אור פני ה' מקרוב עד מ\"ת ורק באמונ' פשוט' נתאמצו לילך אחרי ה' כמ\"ש ויאמינו בה'<sup data-n=\"72\">4</sup> כו' ובזה ראה ה' תוך נקודת פנימי' עוז התקשרותם הנאמנה לו כמשל האב המסתתר ביותר מבנו ורואה תוך לב הבן שמשתדל בכל לבו לרוץ ולילך אחריו כנ\"ל וזהו לכתך אחרי שבזה הנסיון זכו לראות פב\"פ בבחי' אה\"ר בכפלי' והוא שנק' נשיקין כפולים כמ\"ש ישקני מנשיקות פיהו כו' דמ\"ת הוא מעין דלע\"ל וכמ\"ש ז\"ל ישראל שעמדו על הר<sup data-n=\"73\">5</sup> כו' ומכל זה מובן דמהסתר פנים שבזמן הגלות הארוך יותר נתוסף אה\"ר בכפלי כפלי' בזמן הגאולה דכתיב והשיב לב אבות כו' שהשבה זו הוא החזר' פנים בחיבה יתירה מאד שהיא בכפלי' מאהבה הראשונ' שנק' נשיקין כפולים כנ\"ל וד\"ל. והנה עפ\"י משל הנ\"ל יובן היטב תוקף כח האמונה החזקה שבה יצאו אבותינו ממצרים כמ\"ש לכתך אחרי כו' שהוא הגורם גילוי אור פני אביהם שבשמים שבא בנשיקין כפולים אך הנה כל זה לא יתכן רק בבחי' ההילוך לחפש אביו בדרכיו שהולך בהן תמיד כמובן בפרטי המשל הנ\"ל וכמ\"ש אחרי ה' תלכו שאעפ\"י שהוא הולך רק אחרי ה' מ\"מ הילוך נק' שהולך בדרכי ה' ממש רק שאינו רואהו מקרוב רק מרחוק ה' נרא' לו כנ\"ל אבל הנה ארז\"ל תרי\"ג מצות נתנו למשה ובא חבקוק והעמידן על אחת<sup data-n=\"74\">6</sup> לבד והיא מצות האמונה כמ\"ש וצדיק באמונתו יחיה<sup data-n=\"75\">7</sup> הרי מצות האמונ' כוללת כל התרי\"ג מצות כי הכל הולך אחר המעמיד<sup data-n=\"76\">8</sup> והמקיים. והמעמיד ומקיים מעמיד את הכל כא' והן כל התרי\"ג מצות והן רמ\"ח מ\"ע ושס\"ה ל\"ת ואם<sup data-n=\"77\">9</sup> רמ\"ח מ\"ע ודאי האמונה עיקר המעמיד וכמובן ממשל הנ\"ל בהשתדלות הבן ביותר לילך בדרכי אביו לחפשו שהן רמ\"ח מצות עשה שנקרא דרכי ה' ואורחו' ה' כנ\"ל אבל שס\"ה ל\"ת שהן רק מניעת המעשה בשב ואל תעשה לא נק' הילוך כלל ואיך יתכן בזה לומר לכתך אחרי בתוקף האמונה הפשוט' דוקא וא\"כ איך יכלול גם השס\"ה ל\"ת באמונה דוקא וגם מ\"ש מפסוק וצדיק כו' אין זה רק בקיום מ\"ע שבזה נק' צדיק כמ\"ש וצדקה תהיה לנו<sup data-n=\"78\">10</sup> כי נשמור כידוע. אך הנה יש להקדים",[["69","1","<b>ביום ההוא אסתיר פני</b>: וילך לא, יח [בהיפך הסדר]."],["70","2","<b>ברדיפת פרעה</b>: בשלח יד, ה ואילך."],["71","3","<b>בלכתם במדבר בלא מים</b>: ראה בשלח טו, כב. יז, א. ועוד."],["72","4","<b>ויאמינו בה'</b>: בשלח יד, לא."],["73","5","<b>ישראל שעמדו על הר</b>: שבת קמו, רע\"א."],["74","6","<b>תרי\"ג מצות. . על אחת</b>: ראה מכות כג, סע\"ב ואילך."],["75","7","<b>וצדיק באמונתו יחי'</b>: חבקוק ב, ד. ראה לקמן יא, א."],["76","8","<b>הכל הולך אחר המעמיד</b>: לשון הגמ' שבת טו, ב."],["77","9","<b>ואם</b>: כ\"ה גם בדפו\"ר."],["78","10","<b>וצדקה תהי' לנו</b>: ואתחנן ו, כה."]]],[2800530011,"מארז\"ל ע\"פ זה שמי שמי<sup data-n=\"79\">12</sup> עם י\"ה הן שס\"ה ל\"ת וזכרי עם ו\"ה הן רמ\"ח מ\"ע<sup data-n=\"80\">11</sup> כו' והקושיא ידוע איך הל\"ת הן בי\"ה שלמעלה מו\"ה דזה פלא גדול. והנה ידוע בזהר שרמ\"ח מ\"ע נק' רמ\"ח איברין דמלכא<sup data-n=\"81\">13</sup> והן בחי' ה\"ח כלליים שנמשכי' בבחי' או\"כ דוקא ושרש הל\"ת הן בי\"ה דהויה שהוא בחי' אור מקיף לשמור האורו' עליונים שברמ\"ח מ\"ע כו' ולהבין זה הנה ידוע המשל בזה כמו אב חכם המצו' לבנו יחידו לטוב' נפשו כל הימי' שיהי' הולך בדרכי' ומעשי' שהן מועילי' לטובת חיי נפשו ממש שיחיה בהן חיי עולם ואינו מגלה לו הטעמי' וסודו' הכמוסי' שיש לו במעשי' הטובי' האלה כי אם יגלה לו ימצא הבן באופן הטעם לשנות מעט מאופן הצווי וגם לא יהיה חזק כ\"כ לשמור הצווי אבל כשאין הבן יודע הטעם ישמו' לעשות ככל אשר ציוהו בלי שינוי כלל רק מצד האמונ' הפשוט' שמאמין בכל לבו באביו לעשות כרצונו למעלה מן הטעם לגמרי ויאמין שבודאי המצות האלה הם חיי נפשו אעפ\"י שאינו יודע הטעם ולא יצא לנטות ימין ושמאל אפי' כקש\"י ממש וכ\"ז רק ע\"י תוקף האמונה לבד וכמ\"כ להיפך באותן דברים שצוה לו האב לשמור נפשו מהם מאד כי שנאוי ותעוב הוא בעיני אביו ואומר לו רק באזהרה פשוט' שישמו' מהם ולא יעשה דבר פלוני כי יזיק לנפשו לשחתה ממש אעפ\"י שאין הבן יודע הטעם למה יזהר ויתרחק כ\"כ מהם ואיך שהן דברים רעים המזיקים לנפש עד המות ממש מ\"מ יזהר וישמור נפשו מאד רק מפני תוקף האמונה הפשוטה שמאמין באביו שבודאי הן המה דברים רעים מאד שמזיק לנפשו ויתרחק מהם וגם יהיה שנאוי ותעוב בעיניו גם שאין טעם בדבר כלל כי מה שבעיני אביו נמאס הרע גם בעיניו נמאס מצד אמונתו ועוד והוא העיקר שגזרת אביו עליו שלא יוכל לעבור על רצונו לעשות דבר שהוא נגד רצונו ממש שבזה ודאי יגבר יות' כח האמונה מפני שבזה יש יותר פנימי' ההתקשרות שלא לעבור על רצון אביו גם שאינו מואס בדבר זה עפ\"י טבעו שה\"ז רק מצד גזרת האב בלבד הרי יש בזה תוקף כח האמונה יותר משיחזק במעשה הטוב שצוהו אביו שאינו אלא לעשות רצונו עפ\"י האמונ' לפי שבמעשה הטוב בהיות שבו יש גלוי רצון האב עכ\"פ יתחזק בזה באמונתו הבא' בצרוף קיום רצונו אבל לשמור מדב' שנגד רצונו מצד גזרת האב הוא למעלה מעלה מבחי' גילוי אור שהוא הנק' בחי' מקיף שבהעלם יותר מהעלם וסוד שבמעשה הטוב לנפשו ע\"כ ישמור ויזהר א\"ע בתוקף יותר שכל שיהיה הדבר בהעל' יות' יותר יגבר כח האמונה כמו בצווי המעשה שיותר ישמור לעשו' בלא טעם כנ\"ל וד\"ל וכמו ע\"ד דוגמ' כאשר יצוה האב הרופא לבנו דבר זה תאכל לחיזוק חיי בריאותך ודבר זה לא תאכל ותשמור נפשך ממנו כי יזיק אותך למות ממש ודאי יאמין ליזהר ממנו שלא ימות ויברח ממנו באמונה תקיפה יות' משיתאמץ לאכול דבר המחיה נפשו כו' וד\"ל ומלבד זה הנה יש תוקף כח אמונה בגזרת כיבוד אב שלא לחלל כבודו ולעבור על גזרתו יותר מכיבוד אב לקיים רצונו שאם לא קיים מצותו במעשה עכ\"פ לא פגם וחילל בכבודו משא\"כ כשעוב' על גזירתו פגם וחילל מאד בכבוד אביו וע\"ז ישמור נפשו הרבה יותר וד\"ל ונמצא מובן מכל פרטי המשל הזה בהפרש שבין מ\"ע ול\"ת דרך כלל כידוע שמ\"ע",[["79","12","<b>שמי</b>: ניתוסף ע\"פ דפוס ראשון."],["80","11","<b>זה שמי. . רמ\"ח מ\"ע</b>: שמות ג, טו. בלקו\"ת פקודי ג, ב: בת\"ז בהקדמה ד' ד' סע\"ב וד' ה' ע\"א. ראה גם הנסמן במאמרי אדה\"א דברים ח\"ב ע' תיב וע' תריח? נ\"ך ע' צג."],["81","13","<b>שרמ\"ח מ\"ע. . דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). הנסמן במאמרי אדה\"א ויקרא ח\"א ע' ק. דברים ח\"ד ע' א'קצא. שע\"ת ח\"א מא, סע\"ד ואילך."]]],[2800530012,"נק' דרך החיים והטוב ולהיפך הל\"ת נק' מות ורע ממש כמ\"ש ראה נתתי לפניך<sup data-n=\"82\">1</sup> החיים והטוב והמות והרע כו' וכאשר נצטווינו לילך בדרכי המצו' מעשיו' אעפ\"י שלא נודע לנו סודות וטעמי המצות הרי אמרו מצות א\"צ כוונה<sup data-n=\"83\">2</sup> מפני שבלא כוונה וטעם אין השתדלות קיומן רק מצד האמונ' כנ\"ל בפי' אחרי ה' תלכו שנק' הילוך מאחריו גם שלא נודע לו סוד וטעם הרצון האלקי שיש בזה המעשה הגשמי וגם בלבישת ציצית ותפילין וסוכה ולולב ואתרוג וכה\"ג שנתפרש טעמיהן כמו בציצית וראיתם אותו וזכרתם<sup data-n=\"84\">3</sup> ובתפילין וראו כל ע\"ה<sup data-n=\"85\">4</sup> כי שם ה' כו' ובסוכו' כי בסוכו' הושבתי<sup data-n=\"86\">5</sup> כו' מ\"מ לא נודע סודות ורזין עליונים שיש בשרש מעשיהם למעלה כמו בבחי' או\"פ ואו\"מ שבציצית בל\"ב נ\"ח ותפילין בד' מוחין כו' וכן במקיפי' דאימ' שבסכך והמשכת דעת לנוק' בלולב ואתרוג וכה\"ג בכל המצות ומכ\"ש באותן המצות שלא נתפרש טעמיהן כלל שנק' חוקים כמ\"ש אם בחקתי תלכו<sup data-n=\"87\">6</sup> ומצותי תשמרו כו' וגם מצות ק\"ש שהוא מצות יחוד עליון דע\"ס בעצמות המאציל מ\"מ עיקר המצוה בק\"ש רק לצאת י\"ח בלבד שהוא למעלה מן הטעם כי מצות א\"צ כונה רצונו לומר שלבד שא\"צ הנה הרבה יותר טוב לעשות בלא כונה רק לעשות רצון העליון בלבד מפני שזהו אינו בא רק מכח האמונה הפשוטה דוקא וכמו עד\"מ הנ\"ל באמונ' הבן לעשו' דברי' שצוה האב כשלא גילה לו הטע' שישמור לעשות מצד האמונ' בלתי נטי' ימין ושמאל משא\"כ אם הי' יודע טעם לא היה חזק כ\"כ בלבו והי' נוטה קצת כו' וד\"ל. אך הנה מובן עוד ממשל הנ\"ל שבשמירת ל\"ת שהיא להתרחק מכל דבר רע גמור אשר שנא ה' ותעוב בעיניו כו' הגם שבזה יש יותר העלם אור כי לא נודע כלל טעם ההרחקה כמו לא תלבש שעטנז וכלאים<sup data-n=\"88\">7</sup> ולא תאכל חלב ודם<sup data-n=\"89\">8</sup> וכל מאכלות אסורות כחזיר וכל בהמ' טמאה וכן בביאו' אסורות כעריו' ואעפ\"י שנפשו של אדם מחמדתן<sup data-n=\"90\">9</sup> הרי ימנע מהם רק מצד הגזרה שאביו שבשמים גזר עליו כמו שא' אל יאמר אדם אי אפשי בבשר חזיר אלא אפשי אבל אבי שבשמי' גזר עלי<sup data-n=\"91\">10</sup> כו' וגם אותן ל\"ת שנתפרשו טעמן והשכל מחייבן כגזל וש\"ד ועריו' וחילול שבת וכה\"ג מ\"מ לא נודע סוד ה' איך ומה הפג' הגדול למעל' כו' וזהו כמשל הנ\"ל באזהר' האב להבן שיתרחק מאד לנפשו מדברים המזיקי' ביותר שיזה' נפשו בתוקף אמונ' חזקה לשמור עצמו מכל דבר רע המזיק יותר משיתאמץ לעשות רצון האב במצותיו לפי שיש בזה תוקף אמונה יותר מכפי המדה מב' טעמים א' מפני שדבר ששנאוי ותעוב בעיני אביו ימאס גם הוא לבד הטע' שמזיק לנפשו כו' והב' מצד שתוקף האמונה נתגבר בזה יותר להיותו בהעלם דבר ביותר ונק' מקיף שבהעלם גדול והוא ענין א' עם הטעם הג' שלא לפגום בכבוד אב שזהו הרבה יותר קשה בעיניו ממניעת מעשה שציוהו כנ\"ל וד\"ל וכך יובן במצות ל\"ת שיש בהן ב' טעמים א' מצד ששנאוי ותעוב בעיני ה' והן לנגד רצונו מאד וכאשר באמת ובאמונה מתקשרים בנ\"י שנק' בנים יחייב להיות בהם תוקף כח האמונה בזה יותר שיהי' מואס ברע ולבער הרע בכל כחו עוז כמ\"ש ובערת הרע מקרבך<sup data-n=\"92\">11</sup> וכמו שיברח מדבר הממית כו' והב' מצד גזירת כיבוד אב שלא",[["82","1","<b>ראה נתתי לפניך</b>: נצבים ל, טו [בשינוי ? ראה מאמרי אדה\"א שמות ח\"א ע' ד. וש\"נ]."],["83","2","<b>מצות א\"צ כוונה</b>: ראה עירובין צה, סע\"ב. לקמן כו, ב. כז, ב. סט, א. שע\"ת ח\"א יב, ריש ע\"ב ובהנסמן במ\"מ לשם."],["84","3","<b>וראיתם אותו וזכרתם</b>: שלח טו, לט."],["85","4","<b>וראו כל ע\"ה</b>: תבוא כח, י."],["86","5","<b>כי בסוכו' הושבתי</b>: אמור כג, מג."],["87","6","<b>אם בחקתי תלכו</b>: בחוקותי כו, ג."],["88","7","<b>לא תלבש שעטנז וכלאים</b>: תצא כב, יא. קדושים יט, יט."],["89","8","<b>ולא תאכל חלב ודם</b>: ראה ויקרא ג, יז."],["90","9","<b>כעריו'. . מחמדתן</b>: ראה מכות כג, ב (במשנה)."],["91","10","<b>אל יאמר אדם. . גזר עלי</b>: ראה תו\"כ ס\"פ קדושים. שע\"ת ש' התפלה עא, סע\"ד ואילך."],["92","11","<b>ובערת הרע מקרבך</b>: פ' ראה יג, ו."]]],[2800530013,"לפגום ולחלל כבודו והגם שלא נודע טעם הפגם הגדול כמו בל\"ת שלא נודע טעמיהן אדרב' הוא עצמו הנותן כח ועוז גדול יותר להיו' בתוקף האמונה שעיקר מהות ועצם האמונה הוא דוקא במה שלא נודע טעם הדבר כנ\"ל ועכ\"פ מובן מכל זה שעבודת מעשה המצות הן בבחי' או\"פ בכלי' מכלים שונים לקיום רצון העליון הגם שהוא דוקא באמונה פשוטה וז\"ש וצדיק באמונתו יחי' שהן המצות שנא' בהן וחי בהם<sup data-n=\"93\">12</sup> חיי עולם ודוקא בלא כונה וטעם כנ\"ל אבל הל\"ת שרשן יותר נעלה מהם עד שהוא בא מתוקף האמונה יותר להיות שרשן בבחי' מקיף והעלם גדול ע\"כ מחמת הל\"ת בשב ואל תעשה יומשך בחי' אור מקיף לשמור כל מעשה המ\"ע שיהיו קיימים בכלים שלהם ולא יקבלו החיצונים מהם וז\"ש שמי עם י\"ה שס\"ה ל\"ת שהוא בחי' מקיף לו\"ה שברמ\"ח מ\"ע וד\"ל. ובזה יתורץ הקושיא דלעיל במה שהאמונה כוללת תרי\"ג מצות דוקא וד\"ל:\n<b>וזהו</b> לכתך אחרי במדבר בארץ לא זרועה. דהנה ההילוך אחרי ה' באמונה צריך לכוין הדרך והאורח שלא יסור ימין ושמאל והעיקר הוא שלא יטה מן הדרך הישר כלל וכמ\"ש אחרי ה' תלכו שהילוך זה יהי' רק אחרי ה' ולא להטות מן הדרך ימין ושמאל שאם מטה מן הדרך נק' תועה בדרך עקלתון שיוכל ליזוק בדרך רע למות נפשו בשאול ואבדון<sup data-n=\"94\">13</sup> ושחת<sup data-n=\"95\">14</sup> והן שנק' דרכי שאול<sup data-n=\"96\">15</sup> או אורחות עקלקלו'<sup data-n=\"97\">16</sup> כידוע וזהו העיקר והיסוד בשמירה לנפשו זאת שאם לא יטה כלל מן הדרך הישר ממילא יהי' לנוכח ה' דרכו בקדש במ\"ע וזהו השבח הגדול ששיבח לכנ\"י באמרו לכתך אחרי במדבר דוקא כידוע שהמדבר אין בו דרך כבושה ורוב דרכים שבמדבר בחזקת סכנה מנחשים ושרף ועקרב הן ג' קליפות<sup data-n=\"98\">17</sup> הקשות ורעות לגמרי כמ\"ש במדבר הגדול והנורא הזה<sup data-n=\"99\">18</sup> כו' וידוע שבמדבר העמים<sup data-n=\"100\">19</sup> הוא משכן מקום כל הקליפות הקשות ולזה נשלח השעיר לעזאזל המדברה<sup data-n=\"101\">20</sup> לשאת שם כל עונות ב\"י כו' והיינו מ\"ש בארץ לא זרוע' שם (אין<sup data-n=\"102\">21</sup> ) אור הקדושה כלל כמו במקום חשך ואפילה שלא יזרח שם האו' כלל אך ע\"י שמיר' גדולה בתוקף האמונה הלכו גם במדבר דנחש שרף ועקרב רק אחרי ה' בלי נטי' ימין ושמאל והכניעו בזה למקור הקליפו' שבמדבר העמים כו' וזהו יותר מעלה מגוף ההילוך אחרי ה' במ\"ע כנ\"ל הטעם וד\"ל:\n<b>והנה</b> כ\"ז יזכר לכנ\"י בזכרון עולם לפי שכל אלה מורה על תוקף כח האמונה דכנ\"י בעצם ומהות וזהו שכל התרי\"ג מצות העמידן על אחת והיא מצות האמונה וביותר כח האמונה בשמירת הנפש בשס\"ה ל\"ת שנק' מקיף לשמור הנשמה מקטרוגים העליונים כמו משל הלובש שריון קשקשים להגן מכל חץ כך כתיב וילבש צדקה כשריון<sup data-n=\"103\">22</sup> שהן שס\"ה ל\"ת שמגינים על חיצי האויבים שהן קליפות קשות דרע גמור שלא יגיעו בחץ שחוט לשונם<sup data-n=\"104\">23</sup> לקטרג למעלה ולבלוע ולקבל חיות מן הקדושה רע זה כמ\"ש תיסרך רעתך<sup data-n=\"105\">24</sup> כידוע בענין ויאכלו ישראל בכל פה<sup data-n=\"106\">25</sup> בכל מיני בליע' וכמ\"ש בקום עלינו אדם<sup data-n=\"107\">26</sup> כו' ברוך ה' שלא נתננו טרף לשיניהם<sup data-n=\"108\">27</sup> כו' כידוע",[["93","12","<b>וחי בהם</b>: אחרי יח, ה."],["94","13","<b>בשאול ואבדון</b>: משלי טו, יא. כז, כ. ראה לקו\"ש (שבועות) כרך כג ע' 344. תו\"ח מקץ רטז, ג הערה 42."],["95","14","<b>ושחת</b>: תהלים טז, י. עירובין יט, א."],["96","15","<b>דרכי שאול</b>: משלי ז, כז."],["97","16","<b>אורחות עקלקלו'</b>: ס' שופטים ה, ו [ושם: ארחות]."],["98","17","<b>מנחשים. . ג' קליפות</b>: עקב ח, טו. ראה לקו\"ת נשא כ, א ובהנסמן במ\"מ לשם. שע\"ת ח\"א ד, ב ובהנסמן במ\"מ לשם."],["99","18","<b>במדבר הגדול והנורא הזה</b>: עקב שם [בהוספת תיבת ?הזה\"]."],["100","19","<b>שבמדבר העמים</b>: יחזקאל כ, לה. ראה גם שע\"ת שם ובהנסמן במ\"מ לשם."],["101","20","<b>השעיר לעזאזל המדברה</b>: ראה אחרי טז, ח. כא. מאמרי אדה\"א נ\"ך ע' תצח. וש\"נ."],["102","21","<b>(אין)</b>: תיבה זו ניתוספה במהדורת לעמבערג."],["103","22","<b>וילבש צדקה כשריון</b>: ישעי' נט, יז."],["104","23","<b>בחץ שחוט לשונם</b>: ירמי' ט, ז."],["105","24","<b>תיסרך רעתך</b>: ירמי' ב, יט. ראה מאמרי אדה\"א קונטרסים ע' רמז? הנחות תקע\"ז ע' מב? שע\"ת ח\"א ו, ג ובהנסמן במ\"מ להנ\"ל."],["106","25","<b>ויאכלו ישראל בכל פה</b>: ישעי' ט, יא [ושם: את ישראל ? וכ\"ה בסמוך ו, א]. ראה גם מאמרי אדה\"א נ\"ך ע' צא. וש\"נ. שם ס\"ע קב וס\"ע קיז. דרושי חתונה ח\"ב ע' תריז. הנחות תקע\"ז ע' שלט. שע\"ת ח\"ב שעה\"ת עז, ג. תו\"ח מקץ רטו, ב הערה 42. שם רטו, ג."],["107","26","<b>בקום עלינו אדם</b>: תהלים קכד, ב."],["108","27","<b>ברוך. . טרף לשיניהם</b>: שם שם, ו."]]],[2800530014,"בענין פרות הרעות שבלעו לפרות הטובות ומראיהן רע<sup data-n=\"109\">1</sup> כו' וכן נבלע ישראל בגוים<sup data-n=\"110\">2</sup> בע' שרים וזהו ויאכלו את ישראל בכל פה דהיינו שהטוב נבלע ברע כו' כידוע ונמצא שס\"ה ל\"ת בחי' מקיף לשמור על מ\"ע שנק' רמ\"ח אברין דמלכא כו' שלא יומשך מהם חיות ואור אלקי לחיצונים כלל והיינו שמי עם י\"ה שס\"ה ל\"ת כו' ודוקא י\"ה שהן חו\"ב<sup data-n=\"111\">3</sup> שבמחשבה דוקא לפי שעיקר השמירה מכל דבר רע אינו אלא במחשבה דוקא לפי ששם בחי' פנימי' היחוד דאו\"א שהוא מקור ומקיף לכל היח\"ע שברמ\"ח מ\"ע ולהיפך בפגם המחשבה אז יוסר אור המקיף דחו\"ב ויכול לבא לכל דבר רע וכענין הרהורי עבירה<sup data-n=\"112\">4</sup> שקשים מעבירה אע\"פ שאין עונשין רק על המעשה<sup data-n=\"113\">5</sup> ולא על ההרהור מ\"מ קשה ההרהור במח' מגוף המעשה לפי שמשם הוא בחי' מקיף לשמור ולהגן כנ\"ל וראיה לדבר זה מה שכל מחשבה טובה הקב\"ה מצרפה למעשה<sup data-n=\"114\">6</sup> כידוע ועוד ראיה מן מצות ת\"ת שכנגד כולן<sup data-n=\"115\">7</sup> וארז\"ל לא אבדה הארץ<sup data-n=\"116\">8</sup> רק בעון ביטול תורה שנאמר על מה אבדה הארץ על עזבם<sup data-n=\"117\">9</sup> כו'. והענין הוא מטעם הנ\"ל שהתורה שרשה בחכמה שבמוח הראש והוא מקור ומקיף לכל רמ\"ח אברים שברמ\"ח מ\"ע ע\"כ בעון ביטול תורה נפגם המקיף שבמחשבה ועיון בד\"ת שממילא אין שרש למ\"ע וכאילו פגמו בכל המ\"ע וכמ\"כ השמירה לדבר רע הוא דוקא במחשבה שבמוח וכמו שאנו רואים בחוש שכל סיבת הנפילה ברע גמור אינו רק במחשבה תחלה שיעמיק מחשבתו בדבר רע של זנות וגזל וכה\"ג ומן המחשבה יבא למעשה אבל עיקר סור מרע אינו אלא במחשבה דוקא היינו כאשר מדחה מן המחשבה כל דבר רע בדחי' והרחקה גמורה אזי ממילא לא יבא לידי מעשה ח\"ו וע\"כ הרהורי עבירה קשי' מעבירה כידוע ולזה יובן עכ\"פ שכח האמונה החזקה שבמ\"ע כטבע בנפשותינו הרבה יותר מזה יש כח האמונה בחו\"ב שבמחשבה שבמוח לשמור הנשמה מכל דבר רע להרחיקה ולדחותה בכל כח ועוז כמו טבע חזקה רק מצד האמונה שנק' בחי' מקיף והוא שנקרא בשם עטרת<sup data-n=\"118\">10</sup> כידוע (ויכול להיות שיהיה מקיף זה דאמונה על שקר וגם על דבר רע כמו גנבא אפום מחתרתא<sup data-n=\"119\">11</sup> רחמנא קריא ומה שקורא לה' שיענהו ויעזרנו להצליח בגניבה זו אמיתית מצד האמונה ומה שעושה הרע גמור דגניבה מתאות נפשו הבהמית אינו סותר לזה כלל וזהו מפני שבמקיף דאמונה יש הארה חיצוני' מרחוק מאד שלא נכנס בגלוי אור כלל וזהו ששם שמים תמיד שגור בפי הכל<sup data-n=\"120\">12</sup> וגם בעד שקר ונשבעים לשקר ג\"כ ומ\"מ כח האמונה אמיתת מצד עצמה ע\"כ מצות האמונה היא דוקא שתבא לידי גלוי בכח חזק במוח ולב אע\"פ שירושה היא מאבותינו<sup data-n=\"121\">13</sup> וד\"ל) וזהו שאמר במדרש איכה שויתר ה' על גזל ועריות וש\"ד שהיה בבית ראשון ולא ויתר להם על עון ביטול תורה<sup data-n=\"122\">14</sup> כמ\"ש על מה אבדה הארץ ויאמר ה' על עזבם כו' דהנה בשעת עוז והתקשרות המחשבה ועיון היטב בד\"ת היינו בבחי' י\"ה חו\"ב שבמחשבה דכנ\"י בכלל הרי כנ\"י מקושרים ועומדים במהות מחשבתו ית' שלומד בחכמתו העצמי' שבתורה בכל יום<sup data-n=\"123\">15</sup> אע\"פ שמלובש בעניני' גשמי' אין זה הסתר כלל",[["109","1","<b>ומראיהן רע</b>: מקץ מא, כא. ראה גם תו\"א מקץ לא, סע\"ב. לב, ב. תו\"ח שם רטו, סע\"א ואילך. רטו, ג. שע\"ת ח\"ב עו, סע\"ד ואילך. עט\"ר ש' ר\"ה ע' 52."],["110","2","<b>נבלע ישראל בגוים</b>: הושע ח, ח [בדילוג ? ראה מאמרי אדה\"א בראשית ע' ש? נ\"ך ע' צא, שע\"ת ח\"ב עז, ב ובהנסמן במ\"מ להנ\"ל]."],["111","3","<b>י\"ה שהן חו\"ב</b>: ראה זהר (אד\"ז) האזינו רצ, ב. אגה\"ת פ\"ד. מאמרי אדה\"א דברים ח\"ב ע' שסו וע' תרנו."],["112","4","<b>הרהורי עבירה</b>: ראה יומא כט, א. מאמרי אדה\"א נ\"ך ע' פח? הנחות תקע\"ז ס\"ע יז ואילך? שע\"ת ח\"א ד, ד ובהנסמן במ\"מ להנ\"ל."],["113","5","<b>המעשה</b>: תוקן ע\"פ דפוס ראשון."],["114","6","<b>מחשבה. . מצרפה למעשה</b>: קידושין מ, א."],["115","7","<b>ת\"ת שכנגד כולן</b>: פאה רפ\"א."],["116","8","<b>לא אבדה הארץ</b>: נסמן בסמוך הערה שויתר."],["117","9","<b>על מה. . על עזבם</b>: ירמי' ט. יא. יב."],["118","10","<b>האמונה. . עטרת</b>: ראה לקמן ע' ז. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשמ ואילך. ח\"א ע' ד (בשם המקובלים הראשונים). נביאים ע' רכג (בשם ספרים). לקו\"ת ואתחנן ה, ג. פרדס (שעה\"כ) שכ\"ג, מערכת עטרה. (וראה גם ס' מאירת עינים לר\"י דמן עכו (ירושלים תשל\"ה) לא, ב)."],["119","11","<b>גנבא אפום מחתרתא</b>: ראה ברכות סג, א [ע\"פ גי' הע\"י]. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' ט."],["120","12","<b>ששם שמים. . בפי הכל</b>: ראה גם מאמרי אדה\"א קונטרסים ע' קמב? שע\"ת ח\"א ח, ב ובהנסמן במ\"מ להנ\"ל."],["121","13","<b>האמונה. . שירושה היא מאבותינו</b>: ראה להלן ז, סע\"ב. ט, א. כה, א. תניא פי\"ח ופל\"ג. שע\"ת שם. מאמרי אדה\"א נ\"ך ס\"ע כח ואילך. וש\"נ."],["122","14","<b>שויתר ה' על גזל. . ביטול תורה</b>: ראה פתיחתא דאיכ\"ר ב. ירושלמי חגיגה פ\"א, ה\"ז. להלן ו, ב ממס' יומא. מאמרי אדה\"א נ\"ך ע' צג. וש\"נ."],["123","15","<b>שלומד. . שבתורה בכל יום</b>: ראה ע\"ז ג, ב."]]],[2800530015,"לגבי עצמותו כידוע כי דבריו חיים וקיימים<sup data-n=\"124\">16</sup> כמו במ\"ת ממש ומה גם כידוע דבבחי' מ\"ה דחכ' אין בחי' הלבוש דנוגה מסתיר כלל וכלל וד\"ל:\n<b>והנה</b> יש להקדים<sup data-n=\"125\">17</sup> עוד ענין אחד והוא הידוע דאת זלע\"ז<sup data-n=\"126\">18</sup> עשה האלקים ממש וכמו שיש בסטרא דקדושה כח האמונה האלקי' כך יש בסט\"א כח אמונה שנק' אמונה זרה ולכך אמרז\"ל במס' יומא<sup data-n=\"127\">19</sup> מקדש ראשון נחרב בעון ע\"ז וג\"ע וש\"ד (והקב\"ה ויתר להם עד שעברו עון דביטול תורה דוקא כנ\"ל) ומקדש שני אע\"פ שאנו בקיאין בהן שהיו עוסקים בתו\"מ וג\"ח חרב מפני שנאת חנם שהיה ביניהם ללמדך ששקולה שנאת חנם כנגד ג' עבירות ע\"ז וג\"ע וש\"ד כו' ויש להבין דלמה נחרב המקדש השני בעבור עון שנאת חנם אם היה עוסקים בתו\"מ ובגמ\"ח וכידוע שהיה ברובם ככולם מס\"נ על התורה ומצות כמו בימי חשמנאי שמסרו נפשם על התור' ועבודה כשרצו להשכיחם תו\"מ כו' וכן בדורות הזוגות עד הלל ושמאי ותלמידיהם אחריה' עד ר\"ע וחביריו וכרחב\"ת שנהרגו על קדוה\"ש<sup data-n=\"128\">20</sup> בעבור התו\"מ כידוע ורק בעון שנאת חנם לבד נחרב המקדש מפני שנחשב כע\"ז כו' אך הענין הוא דאת זלע\"ז עשה האלקי' וכנגד האמונה האלקי' שהיה בגלוי גמור בכנ\"י בזמן בית ראשון ובפרט בבחי' גלוי אלקו' ממש בהיכל ק\"ק בארון ולוחות וגלוי אור הנבואה בנביאי' כו' הי' לעומת זה אמונת<sup data-n=\"129\">21</sup> זרות דע\"ז בכו\"מ ובבעל ואשרה וכה\"ג שהיו דבוקי' בעון דע\"ז בכל דורות דמלכי ישראל ויהודה עד דור האחרון שבימי ירמי' וכמו שאמרו הנשי'<sup data-n=\"130\">22</sup> המבכו' את התמוז<sup data-n=\"131\">23</sup> כו' לירמיהו ומאז חדלנו לקטר למלכ' השמי' חסרנו כל<sup data-n=\"132\">24</sup> כו' וכמו כן רוב נביאי השקר שהמ' כמו נביאי הבעל והאשרה כידוע בפרטי חלוקיהם שגם נביא שאומר בדבר ה' ולא לעבוד ע\"ז רק לאיזה דבר מה שלא דיברו ה' ושקר הגיד בשם ה' גם הוא דיבר סרה בשם ה' ולו משפט מות כמו נביאי הבעל<sup data-n=\"133\">25</sup> וכמ\"ש בפ' ראה<sup data-n=\"134\">26</sup> כי יקום בקרבך נביא או חולם חלום כו' ובא האות והמופת כו' נלכ' כו' יומת כי דיבר סרה על ה' כו' ובפ' שופטים<sup data-n=\"135\">27</sup> אמ' אך הנביא אשר יזיד לדבר דבר בשמי אשר לא צויתיו לדבר ואשר ידבר בשם אלקים אחרים ומת הנביא ההוא וכי תאמר איכה נדע הדבר אשר לא דברו ה' אשר ידבר הנביא כו' ולא יהיה הדבר ולא יבא הוא הדבר אשר לא דברו ה' בזדון דברו כו' לא תגור ממנו הרי מובן מפשט הדבר שהנביא המדבר בשם ה' אשר לא דברו ה' ואשר ידבר בשם אלקים אחרים שניהן שווין וזהו עיק' ענין נביאי השקר וכמו הרוח שאמ' אצא והייתי רוח שקר<sup data-n=\"136\">28</sup> בפי כל נביאיו כו' לפי שירד שפע האלקי בזמן בית ראשון בגלוי אמונה אלקי' ע\"י הארון והלוחות לנביאים ע\"כ הי' למנגד לזה בסט' דקליפה בחי' אמונות זרות כוזבות דנביאי השקר ונביאי הבעל להאמין בכו\"מ שהן המשפיעים כל שפע גשמי וכמ\"ש הנשי' ומאז חדלנו כו' והוא היפך גמור להאמונה האלקית שעיקר ענין האמונה האלקית הוא להאמין בו",[["124","16","<b>דבריו חיים וקיימים</b>: ע\"פ ברכת אמת ויציב. ראה גם מאמרי אדה\"א שמות ח\"א ע' קעה."],["125","17","<b>והנה יש להקדים</b>: ראה הנרשם לעיל בריש ההקדמה בהערה 1."],["126","18","<b>דאת זלע\"ז</b>: נסמן לקמן קמו, ב."],["127","19","<b>במס' יומא</b>: יומא ט, ב. ראה הערה דלעיל (ו, א) שויתר."],["128","20","<b>ר\"ע. . וכרחב\"ת. . קדוה\"ש</b>: ברכות סא, ב. ע\"ז יח, ב (לאחרי החורבן)."],["129","21","<b>אמונת</b>: כנצ\"ל: אמונות. וכ\"ה בסמוך בפנים."],["130","22","<b>שאמרו הנשי'</b>: ראה ירמי' מד, טו. יט. כ. כה."],["131","23","<b>הנשי' המבכו' את התמוז</b>: יחזקאל ח, יד. ראה לקו\"ת ואתחנן ה, סע\"ד."],["132","24","<b>ומאז. . חסרנו כל</b>: ירמי' מד, יח [ושם: ומן אז. בדילוג ? ראה הנסמן במ\"מ לשע\"ת ח\"א ה, א]."],["133","25","<b>ולו משפט מות כמו נביאי הבעל</b>: ראה ובהבא לקמן רמב\"ם הל' יסוה\"ת פ\"ט והל' ע\"ז פ\"ה ובמפרשים לשם."],["134","26","<b>בפ' ראה</b>: יג, ב. ג. ו."],["135","27","<b>ובפ' שופטים</b>: יח, כ. כב [בדילוגים]."],["136","28","<b>אצא והייתי רוח שקר</b>: מלכים-א כב, כב."]]],[2800530016,"ית' שהוא המשגיח על הכל השגחה פרטי' וכמ\"ש עיניך פקוחות<sup data-n=\"137\">1</sup> על כל דרכי ב\"א וכתי' משמים הביט ה' כו'<sup data-n=\"138\">2</sup> ועל כל צבא המרום במרום<sup data-n=\"139\">3</sup> ואין רשות לשום מלאך או כוכב לעשות פעולתו בלתי רצון האלקי כתנועת היד בגרזן החוצב וכסוס לגבי רוכבו וכמ\"ש כגרזן ביד החוצב<sup data-n=\"140\">4</sup> וכן אמר הנה ה' רוכב<sup data-n=\"141\">5</sup> על עב קל שנק' עננים למירכב<sup data-n=\"142\">6</sup> והוא מה שאנו אומרים ומסדר את הכוכבים<sup data-n=\"143\">7</sup> במשמרותיהם ברקיע כרצונו ממש אבל נביאי שקר האמינו באמונות כוזבות לעשות מהטפל עיקר והן הכו\"ם שהיו מקטרי' להם שהאמינו בהם שבהם נמסר כח השפע וההנהגה כמ\"ש אותי עזבו מקור כו' לחצוב להם בורות<sup data-n=\"144\">8</sup> נשברים כו' והוא נגד האמונה האלקית ממש לפי שאת זלע\"ז ממש כו' וכמ\"ש ולאום מלאום יאמץ<sup data-n=\"145\">9</sup> ולא נתמלאה צור<sup data-n=\"146\">10</sup> אלא מחורבנה של ירושלים כך היה אז התגברות המנגד לאמונה האלקית שהיה בגלוי בבית ראשון ע\"י אמונות זרות שהם ג\"כ כאותו ענין שהוא באלקות שלא הי' כופרים<sup data-n=\"147\">11</sup> באחדות הפשוט' ח\"ו שהרי היו מקריבין קרבנות ומקיימי' כל המ\"ע רק בעון ע\"ז דבקו בו ע\"י הנביאי שקר ומזה העון נחרב בית ראשון לפי שהאמונה האלקית היה אז בתקפה בגלוי כמו בגילוי שכינה בהיכל ק\"ק שזהו גלוי עצמות אלקות שנק' סובב כ\"ע שצמצם שכינתו בין ב' בדי ארון<sup data-n=\"148\">12</sup> כו' והאמונה עיקרה בעצמות אלקות דלית מחת\"ב<sup data-n=\"149\">13</sup> כלל שנק' סובב כ\"ע (כמו שית' בפנים) ע\"כ נק' האמונה בשם עטרת שהיא כעטרת תפארת ע\"ג הראש כו' ולכך אמר איהו אמת ואיהי אמונה<sup data-n=\"150\">14</sup> דאמונה דכנ\"י בחי' בית קבול להכיל לבחי' אמיתית עצמי' אא\"ס ב\"ה כמו שהוא ממש שנק' אמת כמו אמיתך אלקי<sup data-n=\"151\">15</sup> כו'. אך הנה בבית שני שחסר בו חמשה דברים<sup data-n=\"152\">16</sup> ארון ולוחות<sup data-n=\"153\">17</sup> ונבואה כו' רק אור אלקי מעט מזעיר נשאר בבת קול<sup data-n=\"154\">18</sup> ששמשו בו כו' ולא היה בו בחי' גילוי אלקות כמו שהוא ממש גם בהיכל ק\"ק רק ע\"י לבוש מסתיר האור העצמי והן ע\"י עבודות החיצוניות שבמזבח ושלחן ומנורה לבד שזהו רק בבחי' המשכת אור האלקי כמו שהוא בא בהשתלשלות והתלבשות דממלא כ\"ע כו' וע\"כ לא הי' אז בסטרא דקליפה המנגד לקדושה ג\"כ רק בהתלבשות למטה יותר ולא באמונה זרה ג\"כ דאמונה זרה היא עכ\"פ באלקי' לומר הכוכב ומזל הוא עיקר המשפיע שנק' אמונה זרה באלקי' שנתן אלקים ההנהגה לכו\"מ וכה\"ג אבל מאחר שלא הי' בבית שני גילוי תוקף אור האמונה האלקי' דסובב כ\"ע למטה בגילוי בהיכל ק\"ק לא היה במנגד ג\"כ להסתיר האור בנביאי השקר וכה\"ג רק שירצו אמונות זרות וכוזבות במילי דעלמא והוא ענין עון שנאת חנם שהי' ביניהם דהנה עיקר סיבת שנאת חנם אינו בא רק מצד כח האמונה שמאמין לדברי רכיל ולשון הרע שמדברים לו על רעהו ומתפעל מזה מאד להיות לו לשונא לרדפו לחייו ממש וכן חבירו מאמין עליו לשון הרע ורכילות ונעשה שונא לו לרדפו כו' ואם לא היו מאמינים כלל לדברי רכיל שחבירו דורש רעתו אדרבה מתחזק בלבו שהוא דורש טובתו וכן חבירו עליו הי' או\"נ<sup data-n=\"155\">19</sup> דורשים טוב זע\"ז והיינו רוח עועים<sup data-n=\"156\">20</sup> שנמשך להפריד",[["137","1","<b>עיניך פקוחות</b>: ירמי' לב, יט."],["138","2","<b>משמים הביט ה'</b>: תהלים לג, יג."],["139","3","<b>ועל כל צבא המרום במרום</b>: ישעי' כד, כא [ושם: על צבא]."],["140","4","<b>כגרזן ביד החוצב</b>: מו\"נ ח\"ג פכ\"ט. ישעי' י, טו."],["141","5","<b>הנה ה' רוכב</b>: ישעי' יט, א."],["142","6","<b>עננים למירכב</b>: זהר בא מג, א."],["143","7","<b>ומסדר את הכוכבים</b>: ברכת ק\"ש ערבית."],["144","8","<b>אותי עזבו. . בורות</b>: ירמי' ב, יג [ושם: בארות בארת]. ראה גם תו\"ח נח ס, א ובהערה 11."],["145","9","<b>ולאום מלאום יאמץ</b>: תולדות כה, כג."],["146","10","<b>ולא נתמלאה צור</b>: רש\"י תולדות שם. הנסמן במאמרי אדה\"א דברים ח\"א ע' ס."],["147","11","<b>שלא הי' כופרים</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' רכה ובהנסמן לשם."],["148","12","<b>שצמצם שכינתו. . ארון</b>: במאמרי אדה\"ז על ענינים ע' מג בגמרא. ראה ב\"ר פ\"ד, ד. סה\"מ תקס\"ג ח\"א ס\"ע שמח ואילך [ומקבילו שם ע' שמו ואילך נוסח א']. הנסמן במאמרי אדה\"א בראשית ע' קכט."],["149","13","<b>דלית מחת\"ב</b>: ת\"ז בהקדמה (יז, א)."],["150","14","<b>איהו אמת ואיהי אמונה</b>: ראה זהר בלק קצח, ב. מאמרי אדה\"א ויקרא ח\"א ס\"ע צג ואילך."],["151","15","<b>אמיתך אלקי</b>: תהלים עא, כב."],["152","16","<b>בבית שני. . חמשה דברים</b>: ראה יומא כא, ב ובר\"ח ורש\"י שם."],["153","17","<b>בבית שני. . ולוחות</b>: ראה גם סה\"מ תקס\"ה ח\"ב ס\"ע תשלז. מאמרי אדה\"א במדבר ח\"ב ע' תרלו. וראה גם תניא פנ\"ג (עד, ב)."],["154","18","<b>בבית שני. . בת קול</b>: ראה סוטה מח, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תתמד. וש\"נ. שמות ח\"ב ע' תכד. נ\"ך ע' קמג. וש\"נ."],["155","19","<b>או\"נ</b>: אוהבים נאמנים? אוהבי נפש."],["156","20","<b>רוח עועים</b>: ישעי' יט, יד."]]],[2800530017,"בין הדבקים כדי שיהיה קטרוג למעלה על כולם כי כאשר נעשה חבירו שונא בגשמיות הרי הוא מעורר דינין וקטרוגים קשים על חיי נפשו למעלה ונמשך למטה לעורר עליו עון אשר חטא להיות מזה רצועה לאלקא'<sup data-n=\"157\">21</sup> ממש בבני חיי ומזוני ממש וכן משנאת איש לרעהו יעורר על רעהו קטרוגים עליונים והם מעשה שטן לעשות פרודים והיינו סיבת אריכות הגלות שאין לך עיר ומקום שלא יהיה שנאת חנם מאמונת זרות שמאמין שקר וירדפו איש את רעהו חיים בלעו ומעוררים קטרוגים להשחית הכל ובפרט בדור יתום כזה שגם בראשי גדולי הדור יפול שנאת חנם ביותר (וכמו שהיה בבית ראשון בנשיאי ישראל כמו שאמר במסכת יומא<sup data-n=\"158\">22</sup> אלו שאוכלין ושותין יחד ודוקרין זא\"ז בחרבות שבלשונם כו') ועיקר השנאה שלבד אמונה לדבר רכילות ולה\"ר שקר הוא הקנאה לעשיר ומצליח בפרנסתו שיקנאו בו וישנאהו בתכלית וזה מצוי ביותר בעו\"ה שמחמת זה חץ שחוט לשון<sup data-n=\"159\">23</sup> גובר להרוג לרעהו וזה עונש העשיר ומצליח על אשר לא חמל ולא חס על עני ואביון והכל לעצמו לוקח כל מחיה וכל הטלה יטיל על העני<sup data-n=\"160\">24</sup> ויקיל לעצמו כידוע וה' יכפר וד\"ל<sup data-n=\"161\">25</sup> ):\n<b>ואחר</b> הדברים והאמת האלה יובן היטב בענין כחה של האמונה החזקה איך שכוללת כל מ\"ע ול\"ת כמו כי במצותיך האמנתי<sup data-n=\"162\">26</sup> וגם בבחי' פרטי עניני העבודה שבלב ומוח באוי\"ר שכלי' וטבעי' בכאו\"א לפי מקומו ושעתו וגם בתענוג האלקי שבנשמות בעת הכושר כידוע בענין לבי ובשרי ירננו כו' וכן נכספה וגם כלתה נפשי<sup data-n=\"163\">27</sup> במתיקות ועריבות וידידות<sup data-n=\"164\">28</sup> כו' וכמ\"כ בהיפוכו בעוצם הצער והמרירות על רחוקו מה' אחד עד נקוד' עצם הנפש וכמו בבע\"ת אמיתי כידוע הכל בא רק מכחה של האמונה הנטועה בעצם הנפש וכל אלה הן רק הארות והסתעפות שמסתעפים הימנה בעבודה במוח ולב ומעשה ובתשובה מעומקא דלבא וכן בשבת וי\"ט בהתענג על ה' כו' ולזה צריך כל אדם הקרב אל ה' בתפלה ותשובה ומע\"ט לחזק לבבו מאד בכח ועוז האמונה העצמית<sup data-n=\"165\">29</sup> שהיא במהו\"ע דוקא ומשם דוקא יאיר אור האמת בכל פרטי עבודתו כל יום ויום במוחו ולבו ומעשהו בסור מרע וע\"ט ובתשובה וכו' וע\"ז נאמר חדשים לבקרים<sup data-n=\"166\">30</sup> רבה אמונתיך דוקא שבנשמה האלקית מאיר בכל בוקר מכחה של האמונ' דוקא שע\"ז אמר וצדיק באמונתו יחיה שבה יחיה האדם חיי אלקית וגם חיי פרנסתו בהשגחה האלקית דוקא וד\"ל ולזאת כל העיקר והיסוד לכל העבוד' האלקית היא מצות האמונה הפשוטה דוקא וע\"ז אנו אומרים בהגדה והיא שעמדה לאבותינו ולנו והיא היא מצות האמונה דוקא שזכותה עומדת לעד להציל מכל קטרוג קשה למעלה ולמטה וכמ\"ש לא מאסתים<sup data-n=\"167\">32</sup> כו' לכלותם להפר בריתי אתם כו' וזהו שלא אחד בלבד עמד עלינו כו' (וכמשי\"ת בפני'<sup data-n=\"168\">31</sup> ) וע\"כ ראוי מאד לכל איש לחזק ולעורר כח האמונה שבנפשו שיש בודאי בכל א' מצד ירושתינו מאבותינו כמו טבע ממש וע\"כ לא נתפרש' מצות האמונה בתורה<sup data-n=\"169\">33</sup> כי לא שייך צווי ע\"ז רק לעורר אותה כמו שהי'",[["157","21","<b>רצועה לאלקא'</b>: ראה זהר בהקדמה יא, ב."],["158","22","<b>במסכת יומא</b>: ראה שם ט, ב."],["159","23","<b>חץ שחוט לשון</b>: ע\"פ ירמי' ט, ז."],["160","24","<b>העשיר. . העני</b>: ראה שמו\"ב קאפיטול יב."],["161","25","<b>וד\"ל)</b>: באם סיום החצע\"ג אינו טעות הדפוס. אולי התחלתו הוא לעיל בשו\"ה גובר ? וזה."],["162","26","<b>כי במצותיך האמנתי</b>: תהלים קיט, סו."],["163","27","<b>לבי ובשרי ירננו. . נפשי</b>: תהלים פד, ג [בהיפך הסדר]."],["164","28","<b>במתיקות ועריבות וידידות</b>: ראה גם לקמן יט, ב. מאמרי אדה\"א בראשית ע' קעו. וש\"נ. שמות ח\"ב ע' רנג וע' רסב. שע\"ת ח\"א מו, א. תו\"ח וישב קצט, א."],["165","29","<b>העצמית</b>: כ\"ה בדפו\"ר. ובמהדורת לעמבערג: בעצמות."],["166","30","<b>חדשים לבקרים</b>: איכה ג, כג. ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' יד ואילך. וש\"נ. שע\"ת ח\"א ז, ד."],["167","32","<b>לא מאסתים</b>: בחוקותי כו, מד."],["168","31","<b>והיא שעמדה. . בפני'</b>: ראה לקמן יא, א."],["169","33","<b>לא נתפרש' מצות האמונה בתורה</b>: ראה לקמן ט, א. יא, סע\"א ואילך. שע\"ת ח\"א ח, ב ובהנסמן במ\"מ לשם."]]],[2800530018,"לבא בגילוי אורה בכחה ותקפה בלבד וד\"ל ואח' חיזוק האמונה באמת יוכל כל אדם לפי ערכו לבא לבחי' גלוי אור הדעת האלקי בפרטי התפעלות שבהתבוננות ביח\"ע ויח\"ת בק\"ש שזהו מצות היחוד באלקו' בהשגה והכר' במוח ולב בכל חד לפום שיעורא דילי' ונכלל בזה גם מצות אוי\"ר בב\"פ דק\"ש<sup data-n=\"170\">1</sup> בהיות שאוי\"ר שכליי' וגם טבעי' מסתעפים רק מכח הקליט' וההכר' במוח ולב כמ\"ש שמע ישראל ואח\"כ ואהבת וגם לעבדו בקבלת עמ\"ש כידוע כל זה ליודעים וכו'. ועל כל אלה שנרא' בעליל לכל רואה בעין השכל קוטב ויסוד לכל העבודה האלקי' הכל הולך אחר המעמיד<sup data-n=\"171\">2</sup> ומקיים שהוא האמונה וגם במה שאחריה שהוא מצות הדעת אלקית כמ\"ש וארשתיך לי באמונה<sup data-n=\"172\">3</sup> וידעת את ה' וכמ\"ש וידעת היום והשבות אתה הראת<sup data-n=\"173\">4</sup> לדעת כו' וכנ\"ל בענין לאו דשכח' כו'. לזאת אמרתי לעורר לבב אחיי וריעיי אנשים כערכי אע\"פ שהורגלנו כבר בקבלה בלב ומוח בפרטי ידיעות אלקית לא יטעו בנפשם לומר הנה זהו תכלית אמיתית האור כי טוב הוא לטועמיהם גם בהתפעלות התענוג האלקי בעת הכושר כשבת וי\"ט אלא יראו באמת לאמיתו ביסוד האמיתי לכל העבודה האלקית במוח ולב ומעשה שהוא מצות האמונה דוקא ואמרתי ללקט דברי אמת בענין ומהות האמונ' ומצורף לזה לקטתי באמרים דרושים יקרים ונחמדים בקי\"ס ויצ\"מ ששייך לענין האמונ' ולא לדרשה קא אתינא כי אין כאן רק דברים מלוקטים ומיוסדים על דרכי אור האמת שהאיר לנו אבא מארי הגאון ז\"ל בדרשותיו שנתקבלו כבר בלב כל שומע ומבין וכל איש החפץ ומשתוקק ימצא מרגוע לנפשו וגם בצוק העתים כאלה ישים לבו היטב הדק לקרב אל ה' באמונה חזק' בכל עצמיות נפשו וד\"ל ועוד ראיתי לחבר לחלק זה שנק' שער האמונה דברים שמדברים בענין היחוד אלקות בכל פרט ופרט בסדר ההשתלשלות דע\"ס דאבי\"ע והוא קיצור מכל אשר יוכל איש לקר'<sup data-n=\"174\">5</sup> אל השכל בהשגה מלובשת ונתפסת במוח ולב בכל פרטי סדר ההשתלשלות מצמצום הראשון עד סוף עולם העשיה והוא הנק' בשם קונטרס ההתבוננות שרבים משתוקקים שיובא בדפוס כי רבו בו הטעות מאד בהעתקות שונות ומובטחני מאד שיקובל לרצון לפני ה' כונתי הרצוי' לטובת כל איש דורש אלקים באמת ובתמים וידינוני לזכות בכל אשר לא יוכשר בעיני חכמים וכמ\"ש שגיאות<sup data-n=\"175\">6</sup> כו' וה' ירים קרן ישראל ויאיר עיניהם באור ה' אור עולם בחן וחסד ורחמים בחיי הנשמה וחיי הגוף וינטלם וינשאם כל ימי עולם<sup data-n=\"176\">7</sup> עד ביאת הגואל ככל דברי המדבר באמת לאהבת אור האמת והאמונה אוהב דבק מאח<sup data-n=\"177\">8</sup> אחוז וקשור בחבלי עבותות אה\"ר ואה\"ע לכל מבקשי ודורשי אלקים בדרכי האמת בתו\"מ ותפלה ותשובה מקרב ולב עמוק נאום דוב בער באאמו\"ר הגאון מהור\"ר שניאור זלמן זצ\"ל נ\"ע:",[["170","1","<b>מצות אוי\"ר בב\"פ דק\"ש</b>: ראה סידור שער התפילין טו, סע\"ד ואילך. תו\"ח נח נח, ב ובהערה 30."],["171","2","<b>הכל הולך אחר המעמיד</b>: לשון הגמ' שבת טו, ב."],["172","3","<b>וארשתיך לי באמונה</b>: הושע ב, כב."],["173","4","<b>וידעת היום. . אתה הראת</b>: ואתחנן ד, לט. לה."],["174","5","<b>לקר'</b>: תוקן ע\"פ דפו\"ר."],["175","6","<b>שגיאות</b>: תהלים יט, יג."],["176","7","<b>וינטלם. . ימי עולם</b>: ישעי' סג, ט."],["177","8","<b>אוהב דבק מאח</b>: משלי יח, כד."]]]]});
